    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(3):
                if k == 0:
                    # First path
                    if i > 0 and dp[i-1][j][k] != float('-inf'):
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j])
                    if j > 0 and dp[i][j-1][k] != float('-inf'):
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j])
                elif k == 1:
                    # Second path in the same cell
                    if i > 0 and j > 0 and dp[i-1][j-1][k-1] != float('-inf'):
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j-1][k-1] + grid[i][j])
                else:
                    # Second path different from the first
                    if i > 0 and dp[i-1][j][k-1] != float('-inf'):
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j])
                    if j > 0 and dp[i][j-1][k-1] != float('-inf'):
