from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Directions for moving right (0,1) and down (1,0)
    directions = [(0, 1), (1, 0)]

    # Initialize DP table
    dp = [[[0 for _ in range(N)] for _ in range(N)] for _ in range(2)]

    # Fill the DP table
    for i in range(2):
        for x in range(N):
            for y in range(N):
                if i == 0:
                    dp[i][x][y] = grid[x][y]
                else:
                    max_val = 0
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < N and 0 <= ny < N:
                            max_val = max(max_val, dp[i-1][nx][ny])
                    dp[i][x][y] = grid[x][y] + max_val

    # The result is the maximum value collected on the two paths
    return max(dp[0][N-1][N-1], dp[1][N-1][N-1])
