        return len(set(num)) == len(num) and all(int(digit) != 0 for digit in num)

    combinations = []

    for first_digit in '123456789':
        for second_digit in '123456789':
            if second_digit == first_digit:
                continue
            if int(second_digit) != 2 * int(first_digit):
                continue

            for third_digit in '123456789':
                if third_digit == first_digit or third_digit == second_digit:
                    continue
                if int(third_digit) != 3 * int(first_digit):
                    continue

                first_num = int(first_digit + second_digit)
                second_num = int(third_digit)
                third_num = int(first_digit + second_digit + third_digit)

                if is_valid_number(str(first_num)) and is_valid_number(str(second_num)) and is_valid_number(str(third_num)):
                    combinations.append((first_num, second_num, third_num))

    return sorted(combinations)
