def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    level = 1
    while N > level:
        N -= level
        level += 1

    path = []
    for _ in range(level - 1):
        if level % 2 == 0:
            N, level = level - N, N
        else:
            N = N - 1
        path.append(N)

    if level % 2 == 0:
        numerator = 1 + path[-1]
        denominator = level - path[-1]
    else:
        numerator = level - path[-1]
        denominator = 1 + path[-1]

    return f"{numerator}/{denominator}"
```

