    if N <= 0:
        raise ValueError("N must be a positive integer")

    k = 1
    while N > 2 * k - 1:
        N -= 2 * k - 1
        k += 1

    row = 2 * k - N
    col = N - k + 1

    if k % 2 == 0:
        return f"{col}/{row}"
    else:
        return f"{row}/{col}"
