def max_product(num_str: str, N: int, K: int) -> int:
    # Edge case: If K is 0, no multiplication signs are added, so the product is the number itself
    if K == 0:
        return int(num_str)

    # Edge case: If N is 0, the string is empty, so the product is 0
    if N == 0:
        return 0

    # Edge case: If K is greater than or equal to N-1, we can place multiplication signs between every two digits
    if K >= N-1:
        return int(''.join(num_str[i] + '1' for i in range(N-1)) + num_str[-1])

    # Split the string into groups of digits based on K multiplication signs
    splits = ['1'] * K + [num_str]
    for i in range(1, N):
        splits[-1] += num_str[i]

    # Calculate the product of the substrings
    product = 1
    for substring in splits:
        product *= int(substring)

    return product
