def max_product(num_str: str, N: int, K: int) -> int:
    # Check for invalid inputs
    if not num_str.isdigit() or not num_str:
        raise ValueError("num_str must be a non-empty string of digits")
    if not isinstance(N, int) or N <= 0 or N != len(num_str):
        raise ValueError("N must be a positive integer equal to the length of num_str")
    if not isinstance(K, int) or K < 0 or K > N - 1:
        raise ValueError("K must be a non-negative integer less than or equal to N-1")

    # Base case: if no multiplication signs are needed
    if K == 0:
        return int(num_str)

    # Initialize the maximum product to a very small number
    max_product = float('-inf')

    # Try inserting multiplication signs at all possible positions
    for i in range(1, N):
        # Split the number string into two parts
        part1 = num_str[:i]
        part2 = num_str[i:]

        # Calculate the product of the two parts
        current_product = int(part1) * int(part2)

        # Recursively calculate the product of the remaining parts if K-1 multiplication signs are needed
        if K > 0:
            current_product *= max_product(part2, N - i, K - 1)

        # Update the maximum product
        if current_product > max_product:
            max_product = current_product

    return max_product

