def max_product(num_str: str, N: int, K: int) -> int:
    # Edge cases: if K is 0, the number remains the same
    if K == 0:
        return int(num_str)

    # If N is 0, return 0 as it's impossible to get a product with an empty string
    if N == 0:
        return 0

    # If K is greater than or equal to N, all digits can be separated by multiplication signs
    if K >= N - 1:
        return 1

    # Convert the string into a list of integers for easier manipulation
    digits = [int(d) for d in num_str]

    # Remove the smallest digits to maximize the product
    for _ in range(K):
        min_idx = digits.index(min(digits))
        digits[min_idx] = 0

    # Calculate the product of the remaining digits
    product = 1
    for d in digits:
        if d != 0:
            product *= d

    return product
```

