        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            digit = int(char) if char != 'X' else 10
            total += digit * (10 - i)
        return total % 11

    parts = isbn.split('-')
    if len(parts) != 4 or len(parts[2]) != 6:
        raise ValueError("Invalid ISBN format")

    calculated_checksum = calculate_checksum(isbn[:-1])
    expected_checksum = int(isbn[-1])

    if calculated_checksum == expected_checksum:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + str(10 - calculated_checksum if calculated_checksum else 'X')
