def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i in range(10):
            if isbn[i] == 'X':
                digit = 10
            else:
                digit = int(isbn[i])
            total += digit * (10 - i)
        return total % 11

    def is_valid_format(isbn: str) -> bool:
        parts = isbn.split('-')
        return len(parts) == 4 and len(parts[2]) == 6 and parts[0].isdigit() and parts[1].isdigit() and parts[3].isdigit()

    if not is_valid_format(isbn):
        raise ValueError("Invalid ISBN format")

    groups = isbn.split('-')
    isbn_digits = ''.join(groups[2])
    calculated_checksum = calculate_checksum(isbn_digits)

    if calculated_checksum == 0:
        correct_checksum = '0'
    elif calculated_checksum == 1:
        correct_checksum = 'X'
    else:
        correct_checksum = str(11 - calculated_checksum)

