def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        digits = isbn.replace('-', '')
        for i, char in enumerate(digits[:-1]):
            total += (10 - i) * int(char)
        return total % 11

    def is_valid(isbn: str) -> bool:
        return calculate_checksum(isbn) == 0

    def correct_isbn(isbn: str) -> str:
        digits = isbn.replace('-', '')
        for i in range(10):
            corrected_digits = digits[:9] + str(i)
            if calculate_checksum(corrected_digits) == 0:
                return isbn[:9] + str(i)
        return isbn

    if not isbn:
        raise ValueError("ISBN cannot be empty")

    if not isbn.replace('-', '').isdigit():
        raise ValueError("ISBN should only contain digits and dashes")

    if len(isbn.replace('-', '')) != 10:
        raise ValueError("ISBN should have 10 characters")

    if is_valid(isbn):
        return "Right"
    else:
        return correct_isbn(isbn)
