def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0:
        raise ValueError("M and N must be greater than 0")
    if K <= 0:
        raise ValueError("K must be greater than 0")
    if L <= 0:
        raise ValueError("L must be greater than 0")
    if D <= 0:
        raise ValueError("D must be greater than 0")
    if not all(len(pair) == 4 for pair in chatting_pairs):
        raise ValueError("Each chatting pair must contain 4 elements")

    row_counts = [0] * M
    col_counts = [0] * N

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:
            row_counts[Xi - 1] += 1
        elif Yi == Qi:
            col_counts[Yi - 1] += 1

    selected_rows = []
    selected_cols = []

    for _ in range(K):
        max_count = max(row_counts)
        if max_count == 0:
            break
        selected_rows.append(str(row_counts.index(max_count) + 1))
        row_counts[row_counts.index(max_count)] = 0

    for _ in range(L):
        max_count = max(col_counts)
        if max_count == 0:
            break
        selected_cols.append(str(col_counts.index(max_count) + 1))
        col_counts[col_counts.index(max_count)] = 0

    return ' '.join(selected_rows), ' '.join(selected_cols)
