def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n must be greater than 0 and m must be non-negative")

    # Edge case: if m is 0, the ball is already at the starting student
    if m == 0:
        return 1

    # Initialize a 2D list to store the number of ways to reach each student
    dp = [[0 for _ in range(m + 1)] for _ in range(n)]

    # Base case: after 0 passes, each student is at the starting student
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp table
    for j in range(1, m + 1):
        for i in range(n):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    # The result is the number of ways to reach the starting student (index 0) after m passes
    return dp[0][m]
```

