        raise ValueError("Invalid input: n must be a positive integer and m must be non-negative")

    if m == 0 and n > 0:
        return 1

    dp = [[0] * (m + 1) for _ in range(n)]

    for i in range(n):
        dp[i][1] = 2

    for k in range(2, m + 1):
        dp[0][k] = dp[-1][k - 1]
        dp[-1][k] = dp[0][k - 1]
        for i in range(1, n - 1):
            dp[i][k] = dp[i - 1][k - 1] + dp[i + 1][k - 1]

    return dp[0][m]
