def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Create a DP array where dp[i] represents the maximum happiness value that can be achieved with a budget of i
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, happiness in items:
        # Update the DP array from the back to the front to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + happiness)

    # The maximum happiness value that can be achieved with the given budget is the maximum value in the DP array
    return max(dp)
