def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Create a 2D array to store the maximum energy for merging.
    dp = [[0] * n for _ in range(n)]

    # Iterate over the difference between the indices to ensure circularity.
    for length in range(2, n):
        for i in range(n - length):
            j = (i + length) % n
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][(n - 1) % n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        # Determine the sign
        sign = '+' if coeff > 0 else '-'
        if len(terms) == 0 and sign == '+':
            sign = ''  # No leading '+' for the first term

        # Determine the absolute value of the coefficient
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and i > 1:
            abs_coeff = ''  # '1' before 'x' is redundant

        # Determine the variable part
        if i > 1:
            var_part = f'x^{i}'
        elif i == 1:
            var_part = 'x'
        else:
            var_part = ''

        # Construct the term
        term = f'{sign}{abs_coeff}{var_part}'
        terms.append(term)

    return ''.join(terms)

