def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k * x > n or k < 1:
        return 0

    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = 0
    for j in range(k + 1):
        dp[0][j] = 0
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, min(k, i) + 1):
            dp[i][j] = dp[i - j][j] + dp[i][j - 1]

    return dp[n][k] // k_factorial(k)

def k_factorial(k: int) -> int:
    if k == 0:
        return 1
    result = 1
    for i in range(2, k + 1):
        result *= i
    return result

