def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            return "NO ANSWER!"

        for rule in rules:
            source, target = rule
            start = 0

            while start < len(current):
                start = current.find(source, start)
                if start == -1:
                    break

                new_string = current[:start] + target + current[start + len(source):]
                if new_string == B:
                    return steps + 1

                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

                start += 1

    return "NO ANSWER!"

