from collections import deque

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            break

        for src, tgt in rules:
            if src in current:
                new_candidate = current.replace(src, tgt)
                if new_candidate == B:
                    return steps + 1
                if new_candidate not in visited:
                    visited.add(new_candidate)
                    queue.append((new_candidate, steps + 1))

    return "NO ANSWER!"
