from collections import deque
from typing import List, Tuple

def generate_numbers(n: int, rules: List[Tuple[int, int]]) -> int:
    if n < 0:
        raise ValueError("The original number must be non-negative.")

    if not rules:
        return 1  # Only the number itself can be generated if there are no rules.

    # Create a set to store unique numbers
    unique_numbers = set()
    # Create a queue for BFS, starting with the original number as a string
    queue = deque([str(n)])

    while queue:
        current_number_str = queue.popleft()
        current_number = int(current_number_str)

        # If the current number is already in the set, continue to the next one
        if current_number in unique_numbers:
            continue
        unique_numbers.add(current_number)

        # Apply transformation rules to each digit
        for i in range(len(current_number_str)):
            digit = int(current_number_str[i])
            for x, y in rules:
                if digit == x:
                    # Create a new number with the transformed digit
                    new_number_str = current_number_str[:i] + str(y) + current_number_str[i+1:]
                    new_number = int(new_number_str)
                    queue.append(new_number_str)

    return len(unique_numbers)
