from collections import deque

def generate_numbers(n, rules) -> int:
    # Convert the number to a string to easily manipulate individual digits
    num_str = str(n)
    # Initialize a set to keep track of unique numbers generated
    unique_numbers = set([num_str])
    # Initialize a queue for BFS
    queue = deque([num_str])

    # Define a helper function to apply transformation rules to a digit
    def apply_rules(num_str, rules):
        transformed_num_str = list(num_str)
        for old_digit, new_digit in rules:
            transformed_num_str = [str(new_digit) if d == str(old_digit) else d for d in transformed_num_str]
        return ''.join(transformed_num_str)

    # Perform BFS
    while queue:
        current_num_str = queue.popleft()
        # Apply transformation rules to each digit in the current number
        for i in range(len(current_num_str)):
            for old_digit, new_digit in rules:
                if current_num_str[i] == str(old_digit):
                    transformed_num_str = current_num_str[:i] + str(new_digit) + current_num_str[i+1:]
                    if transformed_num_str not in unique_numbers:
                        unique_numbers.add(transformed_num_str)
                        queue.append(transformed_num_str)

    # Return the count of unique numbers generated
    return len(unique_numbers)
