def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Handle edge cases
    if T <= 0 or M <= 0 or not herbs:
        return 0

    # Initialize a 2D DP array
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the DP array
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for t in range(1, T + 1):
            if time <= t:
                dp[i][t] = max(dp[i - 1][t], dp[i - 1][t - time] + value)
            else:
                dp[i][t] = dp[i - 1][t]

    # The answer is in the last cell of the DP array
    return dp[M][T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Check if the total time T is less than the time required for the first herb
    if T < herbs[0][0]:
        return 0

    # Create a list of lists to store the maximum value for each herb
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the dp array
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for j in range(T + 1):
            if j >= time:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum value we can pick with time T is stored in dp[M][T]
    return dp[M][T]

