def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # Create a 2D DP array where dp[i][j] represents the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the dp array for the base case
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]
