def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if not c.isalpha() or not k.isalpha():
            raise ValueError("Input characters must be alphabetic.")
        base = ord('A') if c.isupper() else ord('a')
        k = ord(k.upper()) - base
        c = ord(c.upper()) - base
        result = (c - k) % 26
        return chr(result + base + (0 if c.isupper() else 32))

    decrypted_text = []
    key_length = len(key)
    ciphertext_length = len(ciphertext)

    for i in range(ciphertext_length):
        decrypted_char = shift_char(ciphertext[i], key[i % key_length])
        decrypted_text.append(decrypted_char)

    return ''.join(decrypted_text)
