def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Calculate the longest increasing subsequence (LIS) from the start
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate the longest decreasing subsequence (LDS) from the end
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The minimum number of students to leave is the total number of students
    # minus the sum of the longest increasing and decreasing subsequences plus 1
    # (because the peak is counted twice)
    return n - (max(lis) + max(lds) - 1)
```

