def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        raise ValueError("The number of disc pairs must be a positive integer.")

    # The minimum number of moves required for n pairs of discs in a double-disc Hanoi Towers problem
    # is given by the formula 2 * (2^n - 1)
    return 2 * (2 ** n - 1)
